// why: S10. Schemas are the wire authority. A real compiler checks consumer code, rather than
// searching declarations for strings. Generator controls alter both generated bytes and schema input.
// proves: CLAIM(S10-generated-types) CLAIM(MC1)
import { spawnSync } from "node:child_process";
import { cpSync, readFileSync, writeFileSync } from "node:fs";
import { join, resolve } from "node:path";
import ts from "typescript";
import { expect, it } from "vitest";
import { REPO_ROOT } from "../../test/helpers/fixtures.ts";
import { useTempDirs } from "../../test/helpers/tmp.ts";

const tmp = useTempDirs();
const generator = (args: string[] = []) => spawnSync(process.execPath, ["scripts/gen-types.mjs", ...args], { cwd: REPO_ROOT, encoding: "utf8" });
function diagnostics(source: string): string[] {
  const file = resolve(REPO_ROOT, "test/types/consumer.ts");
  const config = ts.readConfigFile(join(REPO_ROOT, "tsconfig.json"), ts.sys.readFile);
  const options = ts.parseJsonConfigFileContent(config.config, ts.sys, REPO_ROOT).options;
  const host = ts.createCompilerHost(options);
  const read = host.readFile;
  host.readFile = (path) => resolve(path) === file ? source : read(path);
  const program = ts.createProgram([file], options, host);
  return ts.getPreEmitDiagnostics(program).map((d) => `${d.code}: ${ts.flattenDiagnosticMessageText(d.messageText, " ")}`);
}
const contract = () => readFileSync(join(REPO_ROOT, "test/types/envelope.contract.txt"), "utf8");

it("[S10] public Envelope discriminates component data and excludes data for unsupported views", () => {
  expect(diagnostics(contract())).toEqual([]);
});

it("[S10] generator output is current; altered output and a schema-only field change are both detected", () => {
  const current = generator(["--check"]);
  expect([current.status, current.stderr]).toEqual([0, ""]);
  const dir = tmp("type-generation");
  const out = join(dir, "generated");
  const schemas = join(dir, "schemas");
  cpSync(join(REPO_ROOT, "src/generated"), out, { recursive: true });
  cpSync(join(REPO_ROOT, "src/schemas"), schemas, { recursive: true });
  const path = join(out, "ListData.ts");
  const original = readFileSync(path, "utf8");
  writeFileSync(path, original + "// stale declaration\n");
  const altered = generator(["--out", out, "--check"]);
  expect(altered.status).toBe(1);
  expect(altered.stderr).toContain("STALE_TYPES ListData.ts");
  writeFileSync(path, original);
  const schemaPath = join(schemas, "components/list.schema.json");
  const schema = JSON.parse(readFileSync(schemaPath, "utf8"));
  schema.properties.schemaOnlySentinel = { const: "from-schema" };
  schema.required.push("schemaOnlySentinel");
  writeFileSync(schemaPath, JSON.stringify(schema));
  const changedSchema = generator(["--schemas", schemas, "--out", out, "--check"]);
  expect(changedSchema.status).toBe(1);
  expect(changedSchema.stderr).toContain("STALE_TYPES ListData.ts");
  const regenerated = generator(["--schemas", schemas, "--out", out]);
  expect([regenerated.status, regenerated.stderr]).toEqual([0, ""]);
  expect(readFileSync(path, "utf8")).toContain('schemaOnlySentinel: "from-schema"');
  expect(generator(["--schemas", schemas, "--out", out, "--check"]).status).toBe(0);
});

it("[S10] compiler control: generated declarations satisfy the contract; removing one rejection produces an unused expect-error", () => {
  const generated = contract().replace('"../../src/core/wire.ts"', '"../../src/generated/index.ts"');
  expect(diagnostics(generated)).toEqual([]);
  // Positive control for the compiler probe: this marked expression is valid, so the directive MUST fail.
  expect(diagnostics(generated + '\n// @ts-expect-error planted unused rejection\nconst valid: string = "ok";\n')).toEqual([expect.stringContaining("2578:")]);
});
